def compute_chebyshev_output(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [[None]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 or grid[r][c] == 2:
                result[r][c] = grid[r][c]
            else:
                # Check Chebyshev distance to nearest 2
                min_cheby = float('inf')
                for tr in range(rows):
                    for tc in range(cols):
                        if grid[tr][tc] == 2:
                            cheby = max(abs(r-tr), abs(c-tc))
                            min_cheby = min(min_cheby, cheby)

                if min_cheby <= 3:
                    result[r][c] = 1
                else:
                    result[r][c] = 3

    return result

