def find_influence_zones(grid, max_steps=3):
    """Find all cells reachable from each 2 within max_steps using BFS"""
    rows = len(grid)
    cols = len(grid[0])

    result = [[None]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                # Do BFS from this 2
                queue = deque([(r, c, 0)])  # (row, col, steps_from_2)
                visited = set()

                while queue:
                    curr_r, curr_c, steps = queue.popleft()

                    # Add to result grid
                    if result[curr_r][curr_c] is None and grid[curr_r][curr_c] == 2:
                        result[curr_r][curr_c] = ('source', 2, steps)
                    elif result[curr_r][curr_c] is None and grid[curr_r][curr_c] == 3:
                        result[curr_r][curr_c] = ('affected', 1, steps)

                    # Continue BFS
                    if steps < max_steps:
                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = curr_r + dr, curr_c + dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if (nr, nc) not in visited:
                                    visited.add((nr, nc))
                                    queue.append((nr, nc, steps + 1))

    return result

